class Solution {
public:
    int subarraySum(vector<int>& nums) {
        long long res = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int st = max(0, i - nums[i]);
            for (int j = st; j <= i; j++) res += nums[j];
        }
        return (int)res;
    }
};

