class Solution {
public:
    int subarraySum(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        long long res = 0;
        for (int i = 0; i < n; i++)
            res += pre[i + 1] - pre[max(0, i - nums[i])];
        return (int)res;
    }
};

